/bin/bash -c "node <<'NODE'
const CHARSET='qpzry9x8gf2tvdw0s3jn54khce6mua7l';
const GEN=[0x3b6a57b2,0x26508e6d,0x1ea119fa,0x3d4233dd,0x2a1462b3];
function polymod(values){let chk=1;for(const v of values){const top=chk>>>25;chk=((chk&0x1ffffff)<<5)"'^v;for(let i=0;i<5;i++){if((top>>>i)&1) chk ''^= GEN[i];}}return chk;}
function hrpExpand(hrp){const out=[];for(let i=0;i<hrp.length;i++) out.push(hrp.charCodeAt(i)>>>5);out.push(0);for(let i=0;i<hrp.length;i++) out.push(hrp.charCodeAt(i)&31);return out;}
function createChecksum(hrp,data){const values=hrpExpand(hrp).concat(data,[0,0,0,0,0,0]);const mod=polymod(values)''^1;const ret=[];for(let p=0;p<6;p++) ret.push((mod>>>5*(5-p))&31);return ret;}
function encode(hrp,data){return hrp+'"'1'+data.concat(createChecksum(hrp,data)).map(v=>CHARSET[v]).join('');}
function convertbits(data,frombits,tobits,pad=true){let acc=0,bits=0;const ret=[];const maxv=(1<<tobits)-1;const maxAcc=(1<<(frombits+tobits-1))-1;for(const value of data){if(value<0 || (value>>>frombits)"'!==0) return null;acc=((acc<<frombits)|value)&maxAcc;bits+=frombits;while(bits>=tobits){bits-=tobits;ret.push((acc>>>bits)&maxv);}}if(pad){if(bits) ret.push((acc<<(tobits-bits))&maxv);} else if(bits>=frombits || ((acc<<(tobits-bits))&maxv)) return null;return ret;}
const prog=Array(20).fill(0);
const data=[0].concat(convertbits(prog,8,5,true));
console.log(encode('"'bc',data));
NODE"

